import React, { useState, useEffect } from 'react';
import Loader from './components/Loader';
import TypographySample from './pages/TypographySample';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import WhatsAppCta from './components/WhatsAppCta';
import About from './components/About';
import Packages from './components/Packages';
import Commission from './components/Commission';
import HowItWorks from './components/HowItWorks';
import Requirements from './components/Requirements';
import Terms from './components/Terms';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import Footer from './components/Footer';

export default function App() {
  const [loading, setLoading] = useState(true);
  const [typographyDemo, setTypographyDemo] = useState(
    () =>
      typeof window !== 'undefined' &&
      new URLSearchParams(window.location.search).get('demo') === 'typography'
  );

  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 2000);
    return () => clearTimeout(t);
  }, []);

  useEffect(() => {
    const onPop = () =>
      setTypographyDemo(new URLSearchParams(window.location.search).get('demo') === 'typography');
    window.addEventListener('popstate', onPop);
    return () => window.removeEventListener('popstate', onPop);
  }, []);

  if (typographyDemo) {
    return <TypographySample />;
  }

  return (
    <>
      {loading && <Loader />}
      <div style={{ opacity: loading ? 0 : 1, transition: 'opacity 0.5s ease 0.3s' }}>
        <Navbar />
        <Hero />
        <WhatsAppCta />
        <About />
        <Packages />
        <Commission />
        <HowItWorks />
        <Requirements />
        <Terms />
        <Testimonials />
        <Contact />
        <Footer />
        {/* Floating WhatsApp Button */}
      {/* Floating WhatsApp Button with Animation */}
      <a
        href="https://wa.me/923020107044"
        target="_blank"
        rel="noopener noreferrer"
        className="fixed bottom-6 right-6 z-[60] group"
      >
        {/* The Pulse/Ping Effect */}
        <span className="absolute inset-0 rounded-full bg-[#25D366] animate-ping opacity-75"></span>

        {/* The Main Button */}
        <div className="relative bg-[#25D366] text-white p-4 rounded-full shadow-2xl transition-all duration-300 hover:scale-110 active:scale-95 flex items-center justify-center hover:rotate-12">
          <svg
            viewBox="0 0 24 24"
            className="w-8 h-8 fill-current animate-bounce-subtle"
            style={{ animation: 'wiggle 2s infinite' }} // Simple inline wiggle
            xmlns="http://www.w3.org/2000/svg"
          >
            <path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L0 24l6.335-1.662c1.72.937 3.659 1.432 5.631 1.433h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z" />
          </svg>
        </div>

        {/* Tooltip */}
        <span className="absolute right-20 top-1/2 -translate-y-1/2 bg-gray-900 text-white text-xs px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
          Order on WhatsApp
        </span>
      </a>
      </div>
    </>
  );
}
